#!/usr/bin/env bash
set -Eeuo pipefail
PROJECT_ROOT=""; LOCAL_WP_ROOT=""; LOCAL_WP_URL=""; LOCAL_WP_COMMAND="wp"; PRODUCTION_SSH_USER=""; PRODUCTION_SSH_HOST=""; PRODUCTION_SSH_PORT="22"; PRODUCTION_SSH_IDENTITY_FILE=""; PRODUCTION_ROOT=""; PRODUCTION_URL="https://rentacarvenezia.it"; PRODUCTION_EXPECTED_DB_NAME=""; REMOTE_WP_COMMAND="wp"; REMOTE_BACKUP_ROOT='~/rentacar-venezia-production-deployments'; BACKUP_RETENTION_COUNT=10; SYNC_ACTIVE_THIRD_PARTY_PLUGINS=1; REMOTE_PRESERVE_PLUGINS=""; RUN_BROWSER_TESTS=1; AUTO_ROLLBACK_CODE_FAILURE=1
set_config_value() { local key=$1 value=$2; case "$key" in PROJECT_ROOT|LOCAL_WP_ROOT|LOCAL_WP_URL|LOCAL_WP_COMMAND|PRODUCTION_SSH_USER|PRODUCTION_SSH_HOST|PRODUCTION_SSH_PORT|PRODUCTION_SSH_IDENTITY_FILE|PRODUCTION_ROOT|PRODUCTION_URL|PRODUCTION_EXPECTED_DB_NAME|REMOTE_WP_COMMAND|REMOTE_BACKUP_ROOT|BACKUP_RETENTION_COUNT|SYNC_ACTIVE_THIRD_PARTY_PLUGINS|REMOTE_PRESERVE_PLUGINS|RUN_BROWSER_TESTS|AUTO_ROLLBACK_CODE_FAILURE) printf -v "$key" '%s' "$value";; *) warn "ignoring unknown configuration key: $key";; esac; }
load_config() { local p=${1:-}; [ -n "$p" ] || p="$(cd "$DEPLOY_SCRIPT_DIR/.." && pwd)/.env.production"; [ -f "$p" ] || die 2 "configuration not found: $p (run setup)"; CONFIG_FILE=$(absolute_path "$p"); while IFS= read -r line || [ -n "$line" ]; do case "$line" in ''|'#'*) continue;; *=*) set_config_value "${line%%=*}" "${line#*=}";; *) die 2 "invalid configuration line";; esac; done < "$p"; validate_config; }
has_newline() { case "$1" in *$'\n'*|*$'\r'*) return 0;; *) return 1;; esac; }
validate_config() { PROJECT_ROOT=${PROJECT_ROOT:-$(cd "$DEPLOY_SCRIPT_DIR/.." && pwd)}; [ -d "$PROJECT_ROOT" ] || die 2 "PROJECT_ROOT is invalid"; [ -d "$LOCAL_WP_ROOT" ] || die 2 "LOCAL_WP_ROOT is invalid"; PRODUCTION_URL=$(normalize_url "$PRODUCTION_URL") || die 2 "malformed PRODUCTION_URL"; [ "$PRODUCTION_URL" = 'https://rentacarvenezia.it' ] || die 2 "production URL must be canonical rentacarvenezia.it"; case "$PRODUCTION_SSH_PORT" in ''|*[!0-9]*) die 2 "malformed SSH port";; esac; [ "$PRODUCTION_SSH_PORT" -ge 1 ] 2>/dev/null && [ "$PRODUCTION_SSH_PORT" -le 65535 ] || die 2 "malformed SSH port"; for value in "$PRODUCTION_SSH_USER" "$PRODUCTION_SSH_HOST" "$PRODUCTION_ROOT" "$PRODUCTION_EXPECTED_DB_NAME" "$REMOTE_BACKUP_ROOT"; do has_newline "$value" && die 2 "configuration contains a newline"; done; [ -n "$PRODUCTION_SSH_USER" ] && [ -n "$PRODUCTION_SSH_HOST" ] && [ -n "$PRODUCTION_ROOT" ] && [ -n "$PRODUCTION_EXPECTED_DB_NAME" ] || die 2 "production SSH, root, and expected database are required"; case "$PRODUCTION_ROOT" in /|"$HOME"|"$HOME"/) die 2 "unsafe production root";; esac; }
write_production_config() { umask 077; { printf 'PROJECT_ROOT=%s\nLOCAL_WP_ROOT=%s\nLOCAL_WP_URL=%s\nLOCAL_WP_COMMAND=%s\n' "$PROJECT_ROOT" "$LOCAL_WP_ROOT" "$LOCAL_WP_URL" "$LOCAL_WP_COMMAND"; printf 'PRODUCTION_SSH_USER=%s\nPRODUCTION_SSH_HOST=%s\nPRODUCTION_SSH_PORT=%s\nPRODUCTION_SSH_IDENTITY_FILE=%s\nPRODUCTION_ROOT=%s\nPRODUCTION_URL=%s\nPRODUCTION_EXPECTED_DB_NAME=%s\nREMOTE_WP_COMMAND=%s\nREMOTE_BACKUP_ROOT=%s\nBACKUP_RETENTION_COUNT=%s\nSYNC_ACTIVE_THIRD_PARTY_PLUGINS=%s\nREMOTE_PRESERVE_PLUGINS=%s\nRUN_BROWSER_TESTS=%s\nAUTO_ROLLBACK_CODE_FAILURE=%s\n' "$PRODUCTION_SSH_USER" "$PRODUCTION_SSH_HOST" "$PRODUCTION_SSH_PORT" "$PRODUCTION_SSH_IDENTITY_FILE" "$PRODUCTION_ROOT" "$PRODUCTION_URL" "$PRODUCTION_EXPECTED_DB_NAME" "$REMOTE_WP_COMMAND" "$REMOTE_BACKUP_ROOT" "$BACKUP_RETENTION_COUNT" "$SYNC_ACTIVE_THIRD_PARTY_PLUGINS" "$REMOTE_PRESERVE_PLUGINS" "$RUN_BROWSER_TESTS" "$AUTO_ROLLBACK_CODE_FAILURE"; } > "$PROJECT_ROOT/.env.production"; chmod 600 "$PROJECT_ROOT/.env.production"; }
setup_config() { local ssh_line host_part p config_path input; config_path="$(cd "$DEPLOY_SCRIPT_DIR/.." && pwd)/.env.production"; if [ -f "$config_path" ]; then load_config "$config_path"; info 'reusing saved setup values; press Enter to keep a value'; fi; printf 'Hostinger SSH command (ssh [-p PORT] USER@HOST) [%s]: ' "ssh -p $PRODUCTION_SSH_PORT $PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST"; IFS= read -r ssh_line; ssh_line=${ssh_line:-"ssh -p $PRODUCTION_SSH_PORT $PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST"}; set -- $ssh_line; [ "$1" = ssh ] || die 2 "malformed SSH input"; shift; p=22; if [ "${1:-}" = -p ]; then p=${2:-}; shift 2; fi; [ "$#" -eq 1 ] || die 2 "only ssh, optional -p, and USER@HOST are allowed"; host_part=$1; case "$host_part" in *@*) PRODUCTION_SSH_USER=${host_part%@*}; PRODUCTION_SSH_HOST=${host_part#*@};; *) die 2 "SSH user@host is required";; esac; PRODUCTION_SSH_PORT=$p; discover_remote_roots; printf 'Production WordPress root (choose a listed candidate) [%s]: ' "$PRODUCTION_ROOT"; IFS= read -r input; PRODUCTION_ROOT=${input:-$PRODUCTION_ROOT}; printf 'Production database name [%s]: ' "$PRODUCTION_EXPECTED_DB_NAME"; IFS= read -r input; PRODUCTION_EXPECTED_DB_NAME=${input:-$PRODUCTION_EXPECTED_DB_NAME}; printf 'LocalWP root [%s]: ' "${LOCAL_WP_ROOT:-/Users/dvdrb/Local Sites/rentacar-venezia-local/app/public}"; IFS= read -r input; LOCAL_WP_ROOT=${input:-${LOCAL_WP_ROOT:-'/Users/dvdrb/Local Sites/rentacar-venezia-local/app/public'}}; printf 'LocalWP URL [%s]: ' "$LOCAL_WP_URL"; IFS= read -r input; LOCAL_WP_URL=${input:-$LOCAL_WP_URL}; printf 'SSH identity file (blank for agent/interactive) [%s]: ' "$PRODUCTION_SSH_IDENTITY_FILE"; IFS= read -r input; PRODUCTION_SSH_IDENTITY_FILE=${input:-$PRODUCTION_SSH_IDENTITY_FILE}; PROJECT_ROOT=$(cd "$DEPLOY_SCRIPT_DIR/.." && pwd); validate_config; write_production_config; ok 'saved .env.production with mode 600; verifying target'; verify_remote_target; ok 'setup verification completed'; }
